const root = $json;
const headers = root.headers || {};
const receivedKey = String(headers['x-api-key'] || headers['X-API-Key'] || '');
const expectedKey = String($env.N8N_API_KEY || '');

if (!expectedKey || !receivedKey || receivedKey !== expectedKey) {
  throw new Error('Acesso não autorizado ao webhook do portal.');
}

const b = root.body ?? root;
const mode = ['conversation', 'diagnostic'].includes(String(b.mode || 'conversation'))
  ? String(b.mode || 'conversation')
  : 'conversation';

const message = String(b.message || '').trim();
if (!message) throw new Error('Mensagem obrigatória.');

return [{
  json: {
    student_id: String(b.student_id || ''),
    name: String(b.name || 'Aluno'),
    phone: String(b.phone || '').replace(/\D/g, ''),
    message,
    message_type: b.message_type === 'audio' ? 'audio' : 'text',
    is_audio: b.message_type === 'audio',
    channel: String(b.channel || 'web'),
    mode,
    topic: String(b.topic || (mode === 'diagnostic' ? 'initial_diagnostic' : 'daily_life')),
    correction_mode: String(b.correction_mode || 'balanced'),
    conversation: {
      style: String(b.conversation?.style || 'guided'),
      max_turns: Math.max(4, Math.min(30, Number(b.conversation?.max_turns || 10)))
    }
  }
}];

const j = $json;
const s = j.student || {};
const currentStep = Math.max(0, Number(s.diagnostic_step ?? j.diagnostic_step ?? 0) || 0);
const message = String(j.message || '').trim();
const normalized = message
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

const translationRequested = /\b(traduz|traducao|tradução|significa|o que quer dizer|nao entendi|não entendi|pode explicar em portugues|pode explicar em português|i don'?t understand|what does .* mean)\b/i.test(normalized);

function detectChoice(value) {
  const number = value.match(/(?:^|\b)([1-5])(?:\b|$)/);
  if (number) return Number(number[1]);
  if (value.includes('nunca') || value.includes('nao sei nada') || value.includes('zero')) return 1;
  if (value.includes('algumas palavras') || value.includes('reconheco palavras')) return 2;
  if (value.includes('frases simples') || value.includes('escrever frases')) return 3;
  if (value.includes('conversar um pouco') || value.includes('converso um pouco')) return 4;
  if (value.includes('descubra') || value.includes('durante a conversa')) return 5;
  return null;
}

const choices = {
  1: {
    level: 'PRE-A1', band: 'PRE-A1', support: 'pt_first', teaching: 'foundations', language: 'portuguese', explanation: 'pt-BR', correction: 'light',
    reply: `Perfeito. Isso só define por onde começaremos; seu nível será estimado pelas suas respostas.\n\nLeia esta situação:\n\n*Good morning!*\n\nO que essa pessoa está fazendo?\n\n1. Cumprimentando alguém\n2. Pedindo comida\n3. Encerrando a conversa\n\nResponda apenas com 1, 2 ou 3.`
  },
  2: {
    level: 'A1', band: 'A1 inicial', support: 'pt_first', teaching: 'guided', language: 'portuguese', explanation: 'pt-BR', correction: 'light',
    reply: `Ótimo. Isso só define a dificuldade inicial.\n\nComplete a frase sem usar tradutor:\n\n*My name ___ Marina.*\n\n1. is\n2. are\n3. am\n\nResponda apenas com 1, 2 ou 3.`
  },
  3: {
    level: 'A2', band: 'A1–A2', support: 'bilingual', teaching: 'guided_conversation', language: 'adaptive', explanation: 'pt-BR', correction: 'balanced',
    reply: `Ótimo. Agora escreva em inglês uma frase verdadeira sobre algo que você gosta de fazer.\n\nNão precisa estar perfeita e não use tradutor.`
  },
  4: {
    level: 'B1', band: 'A2–B1', support: 'english_first', teaching: 'conversation', language: 'adaptive', explanation: 'adaptive', correction: 'balanced',
    reply: `Great. Answer in two or three sentences:\n\n*What do you usually do after work or school?*\n\nDo not use a translator.`
  },
  5: {
    level: 'A1', band: 'em descoberta', support: 'bilingual', teaching: 'guided_conversation', language: 'adaptive', explanation: 'adaptive', correction: 'balanced',
    reply: `Vamos descobrir pela prática. Leia o texto:\n\n*Daniel works in a store. On Saturdays, he goes to the park with his dog.*\n\nWhere does Daniel go on Saturdays?\n\nResponda em inglês, mesmo que seja com poucas palavras.`
  }
};

function diagnosticBase(overrides = {}) {
  return {
    reply: '',
    current_step: currentStep,
    next_step: Math.min(currentStep + 1, 8),
    complete: false,
    advance: true,
    self_assessment_option: s.initial_self_assessment ?? null,
    provisional_band: '',
    estimated_level: s.estimated_level || s.overall_level || 'PRE-A1',
    confidence: Number(s.diagnostic_confidence || 0),
    language_support: s.preferred_language_support || 'portuguese',
    support_mode: s.support_mode || 'pt_first',
    teaching_mode: s.teaching_mode || 'foundations',
    preferred_explanation_language: s.preferred_explanation_language || 'pt-BR',
    correction_mode: s.correction_mode || 'balanced',
    translation_on_request: true,
    translation_requested: translationRequested,
    audio_sample_received: j.is_audio === true || String(j.message_type || '').includes('audio'),
    scores: {reception:null,interaction:null,production:null,grammar:null,vocabulary:null,fluency:null,coherence:null,pronunciation:null},
    cefr_evidence: [], strengths: [], weaknesses: [], recommendations: [], corrections: [], study_plan: {}, first_activity: {},
    ...overrides
  };
}

let direct = null;
if (currentStep === 0) {
  direct = diagnosticBase({
    reply: `Olá! Eu sou a Emma, sua professora de inglês. 😊\n\nAntes das aulas, faremos uma avaliação breve e adaptativa. Ela não é uma prova e você pode responder com naturalidade.\n\nA sua escolha abaixo serve apenas para eu definir a primeira pergunta; o nível será estimado pelas respostas seguintes.\n\n1. Nunca estudei inglês ou sei muito pouco\n2. Reconheço algumas palavras, mas ainda não formo frases\n3. Consigo entender e escrever frases simples\n4. Consigo conversar um pouco, mesmo cometendo erros\n5. Prefiro que você descubra durante a conversa\n\nResponda com um número de 1 a 5.`,
    next_step: 1,
    self_assessment_option: null,
    provisional_band: 'acolhimento',
    estimated_level: 'PRE-A1',
    confidence: 0,
    support_mode: 'pt_first',
    teaching_mode: 'foundations',
    language_support: 'portuguese',
    preferred_explanation_language: 'pt-BR',
    correction_mode: 'light'
  });
} else if (currentStep === 1) {
  const choice = detectChoice(normalized);
  if (!choice) {
    direct = diagnosticBase({
      reply: `Para escolher a primeira atividade, responda apenas com um número de 1 a 5.\n\n1. Sei muito pouco\n2. Reconheço algumas palavras\n3. Formo frases simples\n4. Consigo conversar um pouco\n5. Prefiro que você descubra`,
      next_step: 1,
      advance: false,
      self_assessment_option: null,
      confidence: 0
    });
  } else {
    const mode = choices[choice];
    direct = diagnosticBase({
      reply: mode.reply,
      next_step: 2,
      self_assessment_option: choice,
      provisional_band: mode.band,
      estimated_level: mode.level,
      confidence: 10,
      support_mode: mode.support,
      teaching_mode: mode.teaching,
      language_support: mode.language,
      preferred_explanation_language: mode.explanation,
      correction_mode: mode.correction
    });
  }
}

const supportMode = s.support_mode || direct?.support_mode || 'pt_first';
const teachingMode = s.teaching_mode || direct?.teaching_mode || 'foundations';
const history = Array.isArray(j.recent_messages) ? j.recent_messages : [];

const diagnosticPrompt = `Você é Emma, professora e avaliadora do RS English. Conduza um diagnóstico pedagógico adaptativo alinhado ao QECR/CEFR.

OBJETIVO
Estimar o nível demonstrado pelo aluno a partir de várias evidências, sem usar a autoavaliação como resultado final.

REGRAS INEGOCIÁVEIS
- Faça somente uma pergunta ou tarefa por resposta.
- Não entregue a resposta antes da tentativa do aluno.
- Não forneça um modelo de frase que já resolva exatamente a pergunta.
- Não repita um exercício já respondido corretamente.
- Se a resposta estiver correta, avance a complexidade; não faça apenas substituição de uma palavra.
- Se a resposta estiver incorreta, dê uma pista curta e proponha uma tarefa equivalente, sem revelar imediatamente a resposta completa.
- Não invente problema de pronúncia sem áudio.
- A classificação é estimativa pedagógica, não certificação oficial.

POLÍTICA ABSOLUTA DE TRADUÇÃO
- NÃO escreva a tradução em português abaixo de cada frase em inglês.
- NÃO use o formato “English sentence (tradução em português)”.
- NÃO traduza automaticamente a nova pergunta.
- Português pode ser usado para orientar o que o aluno deve fazer, mas não para repetir o mesmo conteúdo em outra língua.
- Traduza somente quando Tradução solicitada = true. Nesse caso, traduza apenas a expressão solicitada e mantenha a mesma etapa com advance=false.
- Para PRE-A1/A1, use instrução curta em português e uma única frase-alvo em inglês, sem revelar a resposta.

DADOS
Nome: ${s.name || j.name || 'Aluno'}
Etapa atual: ${currentStep} de 8
Autoavaliação: ${s.initial_self_assessment ?? 'não registrada'}
Faixa provisória: ${s.estimated_level || 'PRE-A1'}
Modo de apoio: ${supportMode}
Modo de ensino: ${teachingMode}
Mensagem atual: ${message}
Mensagem é áudio: ${j.is_audio === true || String(j.message_type || '').includes('audio')}
Tradução solicitada: ${translationRequested}
Histórico recente: ${JSON.stringify(history)}

ETAPAS E EVIDÊNCIAS
2. Avalie a atividade inicial e proponha compreensão contextual curta.
3. Avalie compreensão e proponha estrutura/gramática adequada ao desempenho.
4. Avalie estrutura e proponha leitura curta com uma pergunta de compreensão.
5. Avalie leitura e proponha produção pessoal sem modelo pronto.
6. Avalie produção e proponha tarefa de tempo verbal, sequência ou plano, adaptada ao nível.
7. Avalie interação/coerência e proponha resposta mais independente; convide áudio de 20–30 segundos, mas permita texto.
8. Avalie a última amostra e conclua o diagnóstico com nível, confiança, capacidades observadas, pontos fortes, prioridades e plano inicial.

ADAPTAÇÃO
- Se a resposta mostrar domínio consistente, aumente uma faixa de dificuldade.
- Se houver muitos erros ou bloqueio, reduza a dificuldade sem infantilizar.
- Para PRE-A1/A1, aceite palavras ou frases curtas, mas colete evidências em mais de um tipo de tarefa.
- Para A2/B1, exija conexão entre ideias, rotina, passado/futuro e justificativa simples.
- Para B2+, avalie precisão, variedade, coesão e argumentação.

AVANÇO
- Use advance=false quando a resposta não puder ser avaliada, quando o aluno pedir tradução ou quando for necessário repetir a mesma competência com outra tarefa.
- Use advance=true quando houver evidência suficiente para aquela etapa.
- Complete=true somente na etapa 8 com uma resposta avaliável.

PONTUAÇÃO
- Os scores devem representar a melhor leitura CUMULATIVA das evidências do histórico, não apenas a última mensagem.
- Use null quando ainda não houver evidência suficiente.
- Nunca atribua pronúncia sem áudio.
- O nível final deve refletir o que o aluno demonstrou, não a opção escolhida no início.

Retorne SOMENTE JSON válido:
{
  "reply":"",
  "current_step":${currentStep},
  "next_step":${Math.min(currentStep + 1, 8)},
  "advance":true,
  "complete":${currentStep >= 8},
  "self_assessment_option":${s.initial_self_assessment ?? 'null'},
  "provisional_band":"",
  "estimated_level":"${s.estimated_level || 'PRE-A1'}",
  "confidence":0,
  "language_support":"${s.preferred_language_support || 'portuguese'}",
  "support_mode":"${supportMode}",
  "teaching_mode":"${teachingMode}",
  "preferred_explanation_language":"${s.preferred_explanation_language || 'pt-BR'}",
  "correction_mode":"${s.correction_mode || 'balanced'}",
  "translation_on_request":true,
  "translation_requested":${translationRequested},
  "audio_sample_received":${j.is_audio === true || String(j.message_type || '').includes('audio')},
  "scores":{"reception":null,"interaction":null,"production":null,"grammar":null,"vocabulary":null,"fluency":null,"coherence":null,"pronunciation":null},
  "cefr_evidence":[],
  "strengths":[],
  "weaknesses":[],
  "recommendations":[],
  "corrections":[],
  "study_plan":{},
  "first_activity":{}
}`;

return [{json:{...j,current_step:currentStep,direct_response:Boolean(direct),direct_diagnostic:direct,diagnostic_prompt:diagnosticPrompt,translation_requested:translationRequested}}];

const source = $('Montar Prompt Diagnóstico Web').item.json;
const response = $json;
let text = response.output_text;
if (!text && Array.isArray(response.output)) {
  const parts=[];
  for (const item of response.output) {
    for (const c of (item.content || [])) {
      if (typeof c.text === 'string') parts.push(c.text);
    }
  }
  text=parts.join('\n');
}
text=String(text || '').replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/,'').trim();
let diagnostic=null;
try { diagnostic=JSON.parse(text); } catch (_) {
  const match=text.match(/\{[\s\S]*\}/);
  if (match) try { diagnostic=JSON.parse(match[0]); } catch (_) {}
}

const step=Math.max(2,Number(source.current_step || 2));
const s=source.student || {};
const translationRequested=source.translation_requested === true;

function fallback() {
  const pt=(s.support_mode || 'pt_first') !== 'english_only';
  if (translationRequested) {
    return pt
      ? 'Posso explicar a expressão que você não entendeu. Depois, tente responder à mesma atividade com suas palavras.'
      : 'I can explain the expression you did not understand. Then try the same task again.';
  }
  const prompts={
    2: pt ? 'Vamos tentar outra atividade curta de compreensão. Leia com atenção e responda apenas o que você entendeu.' : 'Let’s try another short comprehension task. Read carefully and answer what you understand.',
    3: pt ? 'Agora complete uma estrutura curta em inglês. Escolha a opção que deixa a frase correta.' : 'Complete a short English structure. Choose the option that makes the sentence correct.',
    4: pt ? 'Leia um pequeno texto em inglês e responda uma pergunta sobre ele.' : 'Read a short English text and answer one question about it.',
    5: pt ? 'Escreva uma frase verdadeira sobre sua rotina, sem usar tradutor.' : 'Write one true sentence about your routine without a translator.',
    6: pt ? 'Conte algo que aconteceu ontem ou um plano para amanhã. Use suas próprias palavras.' : 'Tell me something that happened yesterday or a plan for tomorrow in your own words.',
    7: pt ? 'Responda com um pouco mais de liberdade. Você pode usar texto ou um áudio curto.' : 'Answer more freely. You may use text or a short audio.',
  };
  if (step < 8) return prompts[step] || prompts[7];
  return `Concluímos seu diagnóstico inicial.\n\nNível estimado: ${s.estimated_level || s.overall_level || 'PRE-A1'}.\n\nEssa estimativa será refinada conforme você continuar praticando.\n\nA Emma preparará atividades compatíveis com as evidências registradas.`;
}

if (!diagnostic || typeof diagnostic !== 'object') {
  diagnostic={reply:fallback(),advance:!translationRequested};
}

const levels=['PRE-A1','A1','A2','B1','B2','C1','C2'];
let level=String(diagnostic.estimated_level || s.estimated_level || s.overall_level || 'PRE-A1').toUpperCase();
if (!levels.includes(level)) level='PRE-A1';
const allowedSupport=['pt_first','bilingual','english_first','english_only'];
const allowedTeaching=['foundations','guided','guided_conversation','conversation','immersion'];
const advance=diagnostic.advance !== false && !translationRequested;
const complete=step>=8 && advance;

diagnostic.current_step=step;
diagnostic.advance=advance;
diagnostic.next_step=complete ? 8 : (advance ? Math.min(step+1,8) : step);
diagnostic.complete=complete;
diagnostic.estimated_level=level;
diagnostic.self_assessment_option=diagnostic.self_assessment_option ?? s.initial_self_assessment ?? null;
diagnostic.support_mode=allowedSupport.includes(diagnostic.support_mode)?diagnostic.support_mode:(s.support_mode || 'pt_first');
diagnostic.teaching_mode=allowedTeaching.includes(diagnostic.teaching_mode)?diagnostic.teaching_mode:(s.teaching_mode || 'foundations');
diagnostic.language_support=['portuguese','adaptive','english'].includes(diagnostic.language_support)?diagnostic.language_support:(s.preferred_language_support || 'portuguese');
diagnostic.preferred_explanation_language=['pt-BR','adaptive','en'].includes(diagnostic.preferred_explanation_language)?diagnostic.preferred_explanation_language:(s.preferred_explanation_language || 'pt-BR');
diagnostic.correction_mode=['light','balanced','intensive'].includes(diagnostic.correction_mode)?diagnostic.correction_mode:(s.correction_mode || 'balanced');
diagnostic.confidence=Math.max(0,Math.min(100,Number(diagnostic.confidence || (step*10))));
diagnostic.translation_on_request=true;
diagnostic.translation_requested=translationRequested;
diagnostic.audio_sample_received=Boolean(diagnostic.audio_sample_received || source.is_audio || String(source.message_type || '').includes('audio'));
for (const key of ['cefr_evidence','strengths','weaknesses','recommendations','corrections']) {
  if (!Array.isArray(diagnostic[key])) diagnostic[key]=[];
}
for (const key of ['scores','study_plan','first_activity']) {
  if (!diagnostic[key] || typeof diagnostic[key] !== 'object') diagnostic[key]={};
}
for (const key of ['reception','interaction','production','grammar','vocabulary','fluency','coherence','pronunciation']) {
  if (!(key in diagnostic.scores)) diagnostic.scores[key]=null;
  if (diagnostic.scores[key] !== null) {
    const value=Number(diagnostic.scores[key]);
    diagnostic.scores[key]=Number.isFinite(value)?Math.max(0,Math.min(100,value)):null;
  }
}
if (!String(diagnostic.reply || '').trim()) diagnostic.reply=fallback();
return [{json:{...source,diagnostic,teacher_message:String(diagnostic.reply).trim(),diagnostic_parse_ok:Boolean(text)}}];

const j=$json;
const s=j.student || {};
const prefs=j.student_preferences || {};
const level=s.overall_level || s.estimated_level || 'PRE-A1';
const support=s.support_mode || 'pt_first';
const teaching=s.teaching_mode || 'foundations';
const correction=prefs.correction_mode || s.correction_mode || 'balanced';
const message=String(j.message || '').trim();
const normalized=message.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const translationRequested=/\b(traduz|traducao|tradução|significa|o que quer dizer|nao entendi|não entendi|pode explicar em portugues|pode explicar em português|i don'?t understand|what does .* mean)\b/i.test(normalized);
const blocked=translationRequested || /\b(nao sei responder|não sei responder|nao consigo|não consigo|muito dificil|muito difícil|help me|i can'?t)\b/i.test(normalized);
const conversation=j.conversation || {topic:prefs.conversation_topic || 'daily_life',style:prefs.conversation_style || 'guided',turn_count:0,max_turns:Number(prefs.conversation_max_turns || 10)};

const policy={
  pt_first:'Use português para orientar a atividade. A frase ou pergunta-alvo deve aparecer somente em inglês e sem tradução automática.',
  bilingual:'Combine orientação curta em português com prática em inglês, mas nunca repita a mesma frase nos dois idiomas.',
  english_first:'Use principalmente inglês. Explique em português apenas quando houver pedido explícito ou bloqueio real.',
  english_only:'Use inglês. Volte ao português somente quando houver pedido explícito ou bloqueio real.'
}[support] || 'Adapte o idioma sem duplicar o conteúdo em português e inglês.';

const teachingPolicy={
  foundations:'Ensine do zero, uma habilidade por vez. Não dê a frase completa que o aluno precisa produzir antes da tentativa.',
  guided:'Ofereça instruções e, quando necessário, banco de palavras; evite fornecer a resposta pronta.',
  guided_conversation:'Conduza a conversa com apoio progressivo e retire os modelos conforme o aluno ganha segurança.',
  conversation:'Mantenha conversa natural, corrija sem interromper demais e aumente a complexidade gradualmente.',
  immersion:'Mantenha imersão, naturalidade e desafios compatíveis com o nível.'
}[teaching] || '';

const teacherPrompt=`Você é Emma, professora particular de inglês do RS English.

DADOS
Aluno: ${s.name || j.name || 'Aluno'}
Nível estimado: ${level}
Modo de apoio: ${support}
Modo de ensino: ${teaching}
Modo de correção: ${correction}
Tema: ${conversation.topic || 'daily_life'}
Tradução solicitada: ${translationRequested}
Bloqueio detectado: ${blocked}
Histórico: ${JSON.stringify(j.recent_messages || [])}
Mensagem atual: ${message}

POLÍTICA: ${policy}
METODOLOGIA: ${teachingPolicy}

REGRA ABSOLUTA DE TRADUÇÃO
- Não escreva a tradução em português abaixo de uma frase em inglês.
- Não use o formato “frase em inglês = tradução” em toda interação.
- Não coloque tradução entre parênteses após a pergunta.
- Traduza somente quando Tradução solicitada = true e apenas o trecho pedido.
- Quando o aluno for iniciante, use português para explicar a tarefa e deixe somente a prática-alvo em inglês.

QUALIDADE PEDAGÓGICA
- Não dê a resposta completa antes da tentativa do aluno.
- Não repita o mesmo molde trocando apenas uma palavra por mais de duas interações.
- Quando a resposta estiver correta, confirme de forma breve e avance para uma produção um pouco mais livre.
- Quando houver erro, corrija no máximo o permitido e prossiga com uma pergunta relacionada.
- Use informações reais da resposta do aluno para continuar; evite exercícios genéricos desconectados.
- Faça somente uma pergunta ou tarefa por resposta.
- Não repita pergunta já respondida.
- Se houver bloqueio, reduza a dificuldade e ofereça uma pista ou banco de palavras, não a resposta pronta.
- Para áudio diga “você disse”; para texto diga “você escreveu”.
- Não informe nível ou faça novo diagnóstico agora.

FORMATO DA RESPOSTA
- Reaja primeiro ao conteúdo do aluno.
- Se a frase estiver correta, não precisa reescrevê-la com tradução.
- Use no máximo uma correção essencial no modo light, uma relevante no balanced e duas no intensive.
- Termine com apenas uma nova pergunta ou tarefa.
- Responda somente com a mensagem que será enviada ao aluno.`;

const evaluatorPrompt=`Avalie a mensagem do aluno e retorne somente JSON válido.
Nível: ${level}. Apoio: ${support}. Ensino: ${teaching}. Correção: ${correction}.
Mensagem do aluno: ${message}
Histórico recente: ${JSON.stringify(j.recent_messages || [])}
Retorne: {"grammar_score":null,"vocabulary_score":null,"fluency_score":null,"comprehension_score":null,"corrections":[],"errors":[],"skills":[],"session_complete":false,"session_summary":"","summary_data":{}}.
Não invente pronúncia sem áudio. Não trate resposta curta correta como erro. Limite correções conforme o modo.`;

return [{json:{...j,level,support_mode:support,teaching_mode:teaching,correction_mode:correction,conversation,teacher_prompt:teacherPrompt,evaluator_prompt:evaluatorPrompt,translation_requested:translationRequested}}];

const r = $json;

let text = r.output_text;

if (!text && Array.isArray(r.output)) {
  const parts = [];

  for (const item of r.output) {
    for (const content of item.content ?? []) {
      if (typeof content.text === 'string') {
        parts.push(content.text);
      }
    }
  }

  text = parts.join('\n');
}

text = String(text ?? '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let evaluation;

try {
  evaluation = JSON.parse(text);
} catch (error) {
  evaluation = {
    grammar_score: null,
    vocabulary_score: null,
    fluency_score: null,
    comprehension_score: null,
    corrections: [],
    errors: [],
    skills: []
  };
}

if (!Array.isArray(evaluation.corrections)) {
  evaluation.corrections = [];
}

if (!Array.isArray(evaluation.errors)) {
  evaluation.errors = [];
}

if (!Array.isArray(evaluation.skills)) {
  evaluation.skills = [];
}

return [{
  json: {
    evaluation
  }
}];
